5	import { vmStatus, listSnapshots, listBackups } from "@/lib/proxmox";
6	import { AutoRefresh } from "@/components/AutoRefresh";
7	import { ServerControls } from "@/components/ServerControls";
8	import { CancelService } from "@/components/customer/CancelService";
9	import { terminationRefundCents } from "@/lib/proration";
10	import { RenewalCard } from "@/components/SubscriptionControls";
11	import { StatusDot, Badge, fmtBytes, fmtMoney } from "@/components/ui/primitives";
12	import { MeterBar } from "@/components/ui/charts";
13	import { ServerTabs } from "@/components/customer/ServerTabs";
14	import { MetricsPanel } from "@/components/customer/MetricsPanel";
15	import { DiskUsageChart } from "@/components/customer/DiskUsageChart";
16	import { ServerRename } from "@/components/customer/ServerRename";
17	import { Console } from "@/components/customer/Console";
18	import { OpenTerminalButton } from "@/components/customer/OpenTerminalButton";
19	import { FileManager } from "@/components/customer/FileManager";
20	import { CopyText, RevealPassword, ResetPasswordButton } from "@/components/customer/ServerAccess";
21	import { gameSubdomainBase } from "@/lib/game-subdomain-dns";
22	import { ChangeGameSubdomain } from "@/components/customer/GameSubdomainControl";
23	import { ProjectAssign } from "@/components/customer/ProjectAssign";
24	import { CreateSnapshotForm, SnapshotActions } from "@/components/customer/SnapshotControls";
25	import { CreateBackupButton } from "@/components/customer/BackupControls";
26	import { AddForwardForm, DeleteForwardButton, FirewallPresets, AddFirewallRuleForm, FirewallRuleActions } from "@/components/customer/NetworkingControls";
27	import { firewallPortLabel } from "@/lib/firewall-rules";
28	import { ResizePicker } from "@/components/customer/ResizePicker";
29	import { ResizeDown } from "@/components/customer/ResizeDown";
30	import { AddStorage } from "@/components/customer/AddStorage";
31	import { extraDiskPerGbCents } from "@/lib/disk-expand";
32	import { renewalQuote } from "@/lib/renewal-quote";
33	import { dedicatedIpMonthlyCents } from "@/lib/dedicated-ip";
34	import { annualDiscountPct, frozenAnnualDiscountPct } from "@/lib/annual-discount";
35	import { taxContextForUser } from "@/lib/tax";
36	import { effectiveDiskGB, extraDiskCentsAt } from "@/lib/extra-disk";
37	import { ReinstallOs } from "@/components/customer/ReinstallOs";
38	import { ProvisionErrorBanner } from "@/components/customer/ProvisionErrorBanner";
39	import { ProvisioningOverlay } from "@/components/customer/ProvisioningOverlay";
40	import { serverProvisioningStep } from "@/lib/provisioning-step";
41	import { BackupSchedule } from "@/components/customer/BackupSchedule";
42	import { BackupTierUpsell } from "@/components/customer/BackupTierUpsell";
43	import { backupScheduleHealth } from "@/lib/backup-verify";
44	import { backupPlusMonthlyCents, backupUpgradeQuote } from "@/lib/backup-upgrade";
45	import { backupTierSpec, BACKUP_PLUS_KEEP } from "@/lib/backup-tiers";
46	import { ActivityTimeline } from "@/components/customer/ActivityTimeline";
47	import { SftpAccess } from "@/components/customer/SftpAccess";
48	import { GameAutoUpdate } from "@/components/customer/GameAutoUpdate";
49	import { BackupRestore } from "@/components/customer/BackupRestore";
50	import { GameSettings } from "@/components/customer/GameSettings";
51	import { ControlPanel } from "@/components/customer/cpanel/ControlPanel";
52	import { GameManage } from "@/components/customer/game/GameManage";
53	import { GameMods } from "@/components/customer/GameMods";
54	import { GAME_FAMILIES, type GameFamily } from "@/lib/games";
55	import { familyFor, schemaFor, isValidVariant, validateConfig } from "@/lib/game-config";
56	import { GameServerPanel } from "@/components/customer/gamepanel/GameServerPanel";
57	import { GameSchedules } from "@/components/customer/gamepanel/GameSchedules";
58	import { GamePublicListing } from "@/components/customer/gamepanel/GamePublicListing";
59	import { GameCustomDomain } from "@/components/customer/gamepanel/GameCustomDomain";
60	import type { GameHeaderData } from "@/components/customer/gamepanel/types";
61	
62	export const dynamic = "force-dynamic";
63	
64	function fmtUptime(seconds: number): string {
65	  if (!seconds || seconds <= 0) return "—";
66	  const d = Math.floor(seconds / 86400);
67	  const h = Math.floor((seconds % 86400) / 3600);
68	  const m = Math.floor((seconds % 3600) / 60);
69	  return d > 0 ? `${d}d ${h}h ${m}m` : h > 0 ? `${h}h ${m}m` : `${m}m`;
70	}
71	
72	type LiveStats = {
73	  cpu?: number;
74	  mem?: number;
75	  maxmem?: number;
76	  uptime?: number;
77	  netin?: number;
78	  netout?: number;
79	} | null;
80	
81	export default async function ServerPage({
82	  params,
83	  searchParams,
84	}: {
85	  params: Promise<{ id: string }>;
86	  searchParams: Promise<{ tab?: string; purchase?: string }>;
87	}) {
88	  const [{ id }, { tab, purchase }] = await Promise.all([params, searchParams]);
89	  const user = await requireUser();
90	  const server = await db.server.findUnique({
91	    where: { id },
92	    include: {
93	      plan: true,
94	      osTemplate: true,
95	      project: true,
96	      portForwards: { orderBy: { publicPort: "asc" } },
97	      firewallRules: { orderBy: [{ position: "asc" }, { createdAt: "asc" }] },
98	      jobs: { orderBy: { createdAt: "desc" }, take: 20 },
99	      dedicatedIp: true,
100	      node: true,
101	      // Needed to price a renewal correctly: a game server bills its game plan's
102	      // flat price, not the base VPS plan's term price.
103	      gamePlan: true,
104	    },
105	  });
106	  if (!server || (server.userId !== user.id && user.role !== "ADMIN")) notFound();
107	
108	  // Root password may be stored encrypted-at-rest (rootPasswordEnc); resolve the
109	  // display value through the decrypt fallback (legacy plaintext rows still work).
110	  const rootPassword = serverRootPassword(server);
111	
112	  const [projects, activePlans, osTemplates, extraDiskPriceCents, backupPlusCents, annualPct] = await Promise.all([
113	    db.project.findMany({ where: { userId: server.userId }, orderBy: { name: "asc" } }),
114	    db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
115	    db.osTemplate.findMany({
116	      where: { active: true, category: "PLAIN_OS" },
117	      orderBy: [{ sortOrder: "asc" }, { name: "asc" }],
118	    }),
119	    extraDiskPerGbCents(),
120	    backupPlusMonthlyCents(),
121	    // Live annual discount — feeds the "Renew now" quote below AND the resize
122	    // pickers, so an annual server's renewal/upgrade/downgrade all price against the
123	    // same rate it was sold at.
124	    annualDiscountPct(),
125	  ]);
126	
127	  // VAT/GST for the SERVER OWNER (Finding 1), resolved from their billing country.
128	  const owner =
129	    server.userId === user.id ? user : (await db.user.findUnique({ where: { id: server.userId } })) ?? user;
130	  const renewTaxCtx = await taxContextForUser(owner);
131	
132	  // What "Renew now" will actually charge, priced through the SAME function the
133	  // action charges through, so the button cannot quote one figure and take
134	  // another. See lib/renewal-quote.ts for the incident.
135	  const renewQuote = renewalQuote(
136	    {
137	      termMonths: server.termMonths,
138	      extraDiskGB: server.extraDiskGB,
139	      plan: { name: server.plan.name, priceCents: server.plan.priceCents },
140	      // A game server is sold at its game plan's flat price, NOT the base VPS
141	      // plan it happens to be built on. Omitting this quoted an $8.99 renewal for
142	      // a $4.99 product.
143	      gamePlan: server.gamePlan
144	        ? { name: server.gamePlan.name, priceCents: server.gamePlan.priceCents, termMonths: server.gamePlan.termMonths }
145	        : null,
146	      dedicatedIp: server.dedicatedIp,
147	      backupTier: server.backupTier,
148	    },
149	    {
150	      ipMonthlyCents: server.dedicatedIp ? await dedicatedIpMonthlyCents() : 0,
151	      extraDiskPerGbCents: extraDiskPriceCents,
152	      backupPlusCents,
153	      annualDiscountPct: annualPct,
154	      // VAT/GST for the owner (Finding 1): the "Renews at $X" figure and the Renew
155	      // now quote are tax-inclusive, matching what renewNow charges.
156	      taxRatePercent: renewTaxCtx.ratePercent,
157	    },
158	  );
159	
160	  // The server's REAL disk: plan allowance + any separately-purchased extra disk.
161	  // Every disk figure on this page uses this, never `plan.diskGB` on its own.
162	  const totalDiskGB = effectiveDiskGB(server.plan.diskGB, server.extraDiskGB);
163	
164	  const publicIp = process.env.PUBLIC_IP ?? "";
165	  const transitional = ["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"].includes(server.status);
166	  const busy =
167	    transitional || server.jobs.some((j) => j.status === "QUEUED" || j.status === "RUNNING");
168	  const steady = ["RUNNING", "STOPPED"].includes(server.status);
169	
170	  let live: LiveStats = null;
171	  let snapshots: { name: string; snaptime?: number; description?: string }[] = [];
172	  let backups: { volid: string; ctime?: number; size?: number }[] = [];
173	  let pveUnavailable = false;
174	
175	  if (server.vmid && steady) {
176	    const results = await Promise.allSettled([
177	      vmStatus(server.vmid),
178	      listSnapshots(server.vmid),
179	      listBackups(server.vmid),
180	    ]);
181	    if (results[0].status === "fulfilled") live = results[0].value as LiveStats;
182	    if (results[1].status === "fulfilled") snapshots = results[1].value as typeof snapshots;
183	    if (results[2].status === "fulfilled") backups = results[2].value as typeof backups;
184	    pveUnavailable = results.some((r) => r.status === "rejected");
185	  }
186	
187	  // Dedicated-IP servers connect straight to their own public IP on port 22; NAT
188	  // servers use the platform public IP + the forwarded SSH port. (A dedicated
189	  // server has sshPort=null, which previously fell through to "provisioning…".)
190	  const sshCommand = server.dedicatedIp
191	    ? `ssh root@${server.dedicatedIp.address}`
192	    : server.sshPort
193	      ? `ssh root@${publicIp} -p ${server.sshPort}`
194	      : null;
195	
196	  // Single-item terminal list for this server — connect string computed the
197	  // same way as the Claude Code hub (dedicated IP → own IP, else NAT SSH port).
198	  const terminalServers = [
199	    {
200	      id: server.id,
201	      hostname: server.hostname,
202	      connect: server.dedicatedIp
203	        ? `ssh root@${server.dedicatedIp.address}`
204	        : `ssh -p ${server.sshPort ?? 22} root@${publicIp || "YOUR_SERVER_IP"}`,
205	    },
206	  ];
207	
208	  // SFTP/SSH connection details: dedicated-IP servers connect to their own IP on
209	  // port 22; NAT servers use the platform public IP + the forwarded SSH port.
210	  const dedicated = !!server.dedicatedIp;
211	  const sftpHost = dedicated ? server.dedicatedIp!.address : publicIp || null;
212	  const sftpPort = dedicated ? 22 : server.sshPort;
213	  const isGameServer = GAME_FAMILIES.includes(server.osTemplate.family as GameFamily);
214	
215	  // Post-payment "setting up / it's live" interstitial. Connect string mirrors
216	  // the game-branch's own `connect` computation below (kept in sync manually —
217	  // there's no shared helper today) since that's only computed inside the
218	  // `if (isGameServer)` branch, after this point.
219	  const overlayConnect = isGameServer
220	    ? server.dedicatedIp
221	      ? `${server.dedicatedIp.address}${server.portForwards[0] ? `:${server.portForwards[0].guestPort}` : ""}`
222	      : server.portForwards[0]
223	        ? `${publicIp}:${server.portForwards[0].publicPort}`
224	        : publicIp || null
225	    : sshCommand;
226	  // Real (not cosmetic) step label when the worker has recorded one for this
227	  // server's CURRENT provisioning run — see lib/provisioning-step.ts. Null while
228	  // transitional but no checkpoint reached yet (or in SANDBOX, which completes
229	  // before any step is ever written) simply falls back to the overlay's existing
230	  // cosmetic cycling text.
231	  const liveStep = transitional ? await serverProvisioningStep(server.id) : null;
232	  const overlay = (
233	    <ProvisioningOverlay
234	      serverId={server.id}
235	      status={server.status}
236	      transitional={transitional}
237	      justPaid={purchase === "1"}
238	      provisionError={server.provisionError}
239	      productLabel={isGameServer ? "game server" : "server"}
240	      hostname={server.hostname}
241	      connectAddress={overlayConnect}
242	      planName={isGameServer ? server.gamePlan?.name ?? server.plan.name : server.plan.name}
243	      osName={server.osTemplate.name}
244	      rootPassword={rootPassword}
245	      liveStep={liveStep}
246	      dashboardHref={`/dashboard/servers/${server.id}`}
247	    />
248	  );
249	
250	  // Per-game customization (only for game servers with a customization schema).
251	  const gameFamily = familyFor(server);
252	  const gameSchema = schemaFor(gameFamily);
253	  const gameVariant =
254	    gameSchema && server.gameVariant && isValidVariant(gameFamily!, server.gameVariant)
255	      ? server.gameVariant
256	      : gameSchema?.defaultVariant ?? "";
257	  const gameValidated = gameFamily
258	    ? validateConfig(gameFamily, (server.gameConfig as Record<string, unknown> | null) ?? {})
259	    : null;
260	  const gameValues = gameValidated && gameValidated.ok ? gameValidated.values : {};
261	
262	  /* ---------- Tab: Overview ---------- */
263	  const overview = (
264	    // `grid-cols-1` is load-bearing below `md`. With no base template the browser
265	    // creates an IMPLICIT `auto` track, sized to min-content and unclampable: at
266	    // 390px the rehearsal measured it at 530px — the `ssh root@… -p …` <code> and
267	    // the SFTP/SSH credentials are unbreakable strings — scrolling the whole page
268	    // 156px sideways. `grid-cols-1` compiles to `repeat(1, minmax(0, 1fr))`, the
269	    // same minmax `md:grid-cols-2` already applies, which is why desktop was fine.
270	    <div className="grid grid-cols-1 gap-6 md:grid-cols-2">
271	      <div className="card">
272	        <h2 className="mb-4 font-semibold">Access</h2>
273	        <dl className="space-y-3 text-sm">
274	          <div>
275	            <dt className="text-slate-400">SSH command</dt>
276	            <dd className="mt-1 flex items-center gap-2">
277	              {/* min-w-0 + overflow-x-auto so a long/IPv6 SSH command scrolls
278	                  inside its own box instead of widening the card at 390px —
279	                  parity with the hardened SftpAccess command strings. */}
280	              <code className="min-w-0 flex-1 overflow-x-auto whitespace-nowrap rounded-lg border border-white/10 bg-navy-950/80 px-2.5 py-1.5 font-mono text-xs">
281	                {sshCommand ?? "provisioning…"}
282	              </code>
283	              {sshCommand && <CopyText text={sshCommand} />}
284	            </dd>
285	          </div>
286	          <div className="flex items-center justify-between">
287	            <dt className="text-slate-400">Root password</dt>
288	            <dd>
289	              {rootPassword ? (
290	                <RevealPassword password={rootPassword} />
291	              ) : (
292	                <span className="text-slate-500">—</span>
293	              )}
294	            </dd>
295	          </div>
296	          <div className="flex items-center justify-between">
297	            <dt className="text-slate-400">{dedicated ? "Public IP" : "Private IP"}</dt>
298	            <dd className="font-mono text-xs">{(dedicated ? server.dedicatedIp!.address : server.ipAddress) ?? "—"}</dd>
299	          </div>
300	        </dl>
301	        <div className="divider" />
302	        <div className="flex flex-wrap items-center justify-between gap-2">
303	          <p className="text-xs text-slate-500">
304	            Lost access or rotating credentials? Generate a fresh root password.
305	          </p>
306	          <ResetPasswordButton serverId={server.id} disabled={busy || !steady} />
307	        </div>
308	      </div>
309	
310	      <SftpAccess
311	        host={sftpHost}
312	        port={sftpPort}
313	        password={rootPassword}
314	        dedicated={dedicated}
315	      />
316	
317	      {isGameServer && (
318	        <div className="md:col-span-2">
319	          <GameAutoUpdate
320	            serverId={server.id}
321	            gameName={server.osTemplate.name}
322	            autoUpdate={server.autoUpdate}
323	            canUpdate={server.status === "RUNNING"}
324	            busy={busy}
325	          />
326	        </div>
327	      )}
328	
329	      {server.gamePlanId && gameSchema && (
330	        <div className="md:col-span-2">
331	          <GameSettings
332	            serverId={server.id}
333	            schema={gameSchema}
334	            variant={gameVariant}
335	            values={gameValues}
336	            disabled={busy || !steady}
337	          />
338	        </div>
339	      )}
340	
341	      <div className="card">
342	        <h2 className="mb-4 font-semibold">Live stats</h2>
343	        {live ? (
344	          <div className="space-y-4 text-sm">
345	            <div>
346	              <div className="mb-1.5 flex justify-between">
347	                <span className="text-slate-400">CPU</span>
348	                <span className="font-semibold">{((live.cpu ?? 0) * 100).toFixed(1)}%</span>
349	              </div>
350	              <MeterBar value={(live.cpu ?? 0) * 100} max={100} />
351	            </div>
352	            <div>
353	              <div className="mb-1.5 flex justify-between">
354	                <span className="text-slate-400">Memory</span>
355	                <span className="font-semibold">
356	                  {fmtBytes(live.mem ?? 0)} / {fmtBytes(live.maxmem ?? 0)}
357	                </span>
358	              </div>
359	              <MeterBar value={live.mem ?? 0} max={live.maxmem ?? 1} color="#3b82f6" />
360	            </div>
361	            <div className="flex justify-between">
362	              <span className="text-slate-400">Uptime</span>
363	              <span className="font-semibold">{fmtUptime(live.uptime ?? 0)}</span>
364	            </div>
365	            <div className="flex justify-between">
366	              <span className="text-slate-400">Network I/O</span>
367	              <span className="font-mono text-xs">
368	                {fmtBytes(live.netin ?? 0)} in · {fmtBytes(live.netout ?? 0)} out
369	              </span>
370	            </div>
371	          </div>
372	        ) : (
373	          <p className="text-sm text-slate-400">
374	            {pveUnavailable
375	              ? "Hypervisor is briefly unavailable — stats will reappear shortly."
376	              : "Live stats appear once the server is provisioned."}
377	          </p>
378	        )}
379	      </div>
380	
381	      <div className="card">
382	        <h2 className="mb-4 font-semibold">Configuration</h2>
383	        <dl className="space-y-2.5 text-sm">
384	          <div className="flex justify-between">
385	            <dt className="text-slate-400">Plan</dt>
386	            <dd>
387	              {server.plan.name} — {server.plan.cpuCores} vCPU / {server.plan.ramMB / 1024} GB /{" "}
388	              {totalDiskGB} GB NVMe
389	              {server.extraDiskGB > 0 && (
390	                <span className="block text-xs text-slate-500">
391	                  {server.plan.diskGB} GB plan + {server.extraDiskGB} GB added storage
392	                </span>
393	              )}
394	            </dd>
395	          </div>
396	          <div className="flex justify-between">
397	            <dt className="text-slate-400">Bandwidth</dt>
398	            <dd>{server.plan.bandwidthTB} TB / month</dd>
399	          </div>
400	          <div className="flex justify-between">
401	            <dt className="text-slate-400">Operating system</dt>
402	            <dd>{server.osTemplate.name}</dd>
403	          </div>
404	          <div className="flex justify-between">
405	            <dt className="text-slate-400">Created</dt>
406	            <dd>{server.createdAt.toISOString().slice(0, 10)}</dd>
407	          </div>
408	          <div className="flex justify-between">
409	            <dt className="text-slate-400">{server.isFree ? "Billing" : "Renews"}</dt>
410	            <dd>
411	              {server.isFree
412	                ? "Free — never expires"
413	                : server.expiresAt
414	                  ? server.expiresAt.toISOString().slice(0, 10)
415	                  : "—"}
416	            </dd>
417	          </div>
418	        </dl>
419	      </div>
420	
421	      {!server.isFree ? (
422	        // The "Price /mo" the card shows must agree with what Renew now charges.
423	        // A game server is sold at its game plan's flat price, so its monthly
424	        // run-rate is that price over its term — NOT the base VPS plan.priceCents
425	        // it is built on, which would read $8.99/mo beside a $4.99 renewal on the
426	        // same card. Both figures derive from renewQuote, the single shared
427	        // formula, and extra disk mirrors renewalCharge (game plans carry no
428	        // add-on line, so showing one would overstate the monthly).
429	        <RenewalCard
430	          serverId={server.id}
431	          autoRenew={server.autoRenew}
432	          expiresAt={server.expiresAt ? server.expiresAt.toISOString() : null}
433	          priceCents={
434	            server.gamePlan
435	              ? Math.round(renewQuote.totalCents / renewQuote.months)
436	              : server.plan.priceCents
437	          }
438	          extraDiskGB={server.extraDiskGB}
439	          extraDiskMonthlyCents={server.gamePlan ? 0 : extraDiskCentsAt(server.extraDiskGB, extraDiskPriceCents)}
440	          suspendedUnpaid={server.status === "SUSPENDED" && !!server.suspendedNote?.includes("unpaid")}
441	          renewTotalCents={renewQuote.totalCents}
442	          renewDurationLabel={renewQuote.durationLabel}
443	        />
444	      ) : (
445	        <div className="card">
446	          <h2 className="mb-3 font-semibold">Subscription</h2>
447	          <p className="text-sm text-slate-400">
448	            This server is free of charge — no billing, no expiry.
449	          </p>
450	        </div>
451	      )}
452	
453	      {!server.isFree && server.status !== "DELETING" && (
454	        <div className="card md:col-span-2">
455	          <CancelService
456	            serverId={server.id}
457	            hostname={server.hostname}
458	            expiresAt={server.expiresAt ? server.expiresAt.toISOString() : null}
459	            autoRenew={server.autoRenew}
460	            refundEstimateCents={terminationRefundCents({
461	              isFree: server.isFree,
462	              expiresAt: server.expiresAt,
463	              isGame: !!server.gamePlanId,
464	              planMonthlyCents: server.plan.priceCents,
465	              termMonths: server.termMonths,
466	              termPromoPercent: server.termPromoPercent,
467	              refundableTermCents: server.refundableTermCents,
468	              annualDiscountPct: frozenAnnualDiscountPct(server) ?? annualPct,
469	            })}
470	          />
471	        </div>
472	      )}
473	
474	      <div className="card md:col-span-2">
475	        <h2 className="mb-4 font-semibold">Disk usage</h2>
476	        <DiskUsageChart
477	          serverId={server.id}
478	          planTotalGB={totalDiskGB}
479	          available={!!server.vmid && steady}
480	        />
481	      </div>
482	
483	      <div className="card md:col-span-2">
484	        <h2 className="mb-3 font-semibold">Project</h2>
485	        <ProjectAssign
486	          serverId={server.id}
487	          currentProjectId={server.projectId}
488	          projects={projects.map((p) => ({ id: p.id, name: p.name, color: p.color }))}
489	        />
490	      </div>
491	    </div>
492	  );
493	
494	  /* ---------- Tab: Files ---------- */
495	  const filesPanel =
496	    server.status === "RUNNING" ? (
497	      <FileManager serverId={server.id} />
498	    ) : (
499	      <div className="card py-12 text-center">
