141	  const job = await db.job.findFirst({
142	    where: { serverId: server.id, type: { in: ["BACKUP_CREATE", "BACKUP_RESTORE"] } },
143	    orderBy: { createdAt: "desc" },
144	    select: { id: true, type: true, status: true, progress: true, step: true, error: true, createdAt: true },
