"use client";

import { useState } from "react";

/** Snapshot thresholds — instantaneous values already computed on the page, not a
 * "sustained N minutes" tracker. Simple on purpose (see ProvisionErrorBanner /
 * BackupTierUpsell for the same "small presentational banner" convention). */
const RAM_THRESHOLD_PCT = 90;
const DISK_THRESHOLD_PCT = 90;
const CPU_THRESHOLD_PCT = 90;

/**
 * "You're running low on X — consider upgrading" banner. Pure presentational:
 * renders nothing if every metric is below its threshold, and nothing if a
 * metric wasn't supplied (undefined/null — e.g. VPS overview has no per-page
 * disk sample, so `diskPct` is simply omitted there rather than faked).
 *
 * Dismissible for the current page view only (local state, no persistence) —
 * this is a nudge, not a notification center entry.
 */
export function ResourceLimitAlert({
  cpuPct,
  memPct,
  diskPct,
  upgradeHref,
}: {
  cpuPct?: number | null;
  memPct?: number | null;
  diskPct?: number | null;
  /** Where "Upgrade" should take the customer — the resize/storage section. */
  upgradeHref: string;
}) {
  const [dismissed, setDismissed] = useState(false);

  const hot: string[] = [];
  if (typeof cpuPct === "number" && cpuPct >= CPU_THRESHOLD_PCT) hot.push("CPU");
  if (typeof memPct === "number" && memPct >= RAM_THRESHOLD_PCT) hot.push("RAM");
  if (typeof diskPct === "number" && diskPct >= DISK_THRESHOLD_PCT) hot.push("disk");

  if (dismissed || hot.length === 0) return null;

  const label = hot.length === 1 ? hot[0] : hot.length === 2 ? hot.join(" and ") : `${hot.slice(0, -1).join(", ")} and ${hot[hot.length - 1]}`;

  return (
    <div className="card flex flex-wrap items-center justify-between gap-3 border-amber-500/30 bg-amber-500/[0.06]">
      <div className="flex items-start gap-3">
        <span className="mt-0.5 text-amber-300">⚠</span>
        <div>
          <p className="text-sm font-medium text-amber-200">
            Running low on {label}
          </p>
          <p className="mt-0.5 text-xs text-slate-400">
            Your server is using {hot.length > 1 ? "most" : "nearly all"} of its {label} — consider
            upgrading to a bigger plan before it becomes a bottleneck.
          </p>
        </div>
      </div>
      <div className="flex shrink-0 items-center gap-2">
        <a href={upgradeHref} className="btn-secondary text-xs">
          Upgrade
        </a>
        <button
          type="button"
          onClick={() => setDismissed(true)}
          className="rounded-full px-2 py-1 text-xs text-slate-500 hover:text-slate-300"
          aria-label="Dismiss"
        >
          Dismiss
        </button>
      </div>
    </div>
  );
}

import { fmtMoney } from "@/components/ui/primitives";

export type GameTierSummary = {
  id: string;
  name: string;
  ramMB: number;
  cpuCores: number;
  diskGB: number;
  slots: number | null;
  priceCents: number;
  termMonths: number;
};

/**
 * Game-server "Resize & storage" card.
 *
 * INFORMATIONAL, NOT SELF-SERVICE. A game tier (`GamePlan`) is sold as a fixed,
 * flat-price bundle — `lib/resize.ts` refuses `resizeQuote` outright for any
 * server with a `gamePlanId` ("Game server plans are fixed bundles — switch
 * tiers from the game server's own settings, or contact support"), and
 * `lib/renewal-charge.ts` bills a game plan at ONE flat price with no per-GB
 * disk or backup add-on lines ever added on top ("a game plan is all-in").
 *
 * Wiring the VPS `ResizePicker`/`AddStorage` in here unmodified would either
 * (a) let a customer "resize" onto a raw VPS `Plan` that has nothing to do with
 * what they actually bought, hitting the ResizeError above every time, or
 * (b) let them buy extra disk that is charged once and then rides free on every
 * renewal forever, since `renewalCharge` never re-bills disk for a flat game
 * plan. Neither is a real feature — so this card gives the customer the
 * information those actions can't: what they're on, what else exists, and how
 * to actually move (support does it manually, preserving the world/data).
 */
export function GameTierInfo({
  hostname,
  current,
  otherTiers,
  effectiveDiskGB,
  extraDiskGB,
  supportHref = "/dashboard/support",
}: {
  hostname: string;
  current: GameTierSummary;
  /** Other ACTIVE tiers in the same game family, cheapest first. */
  otherTiers: GameTierSummary[];
  /** plan disk + any extra disk this server holds. */
  effectiveDiskGB: number;
  extraDiskGB: number;
  supportHref?: string;
}) {
  const monthly = Math.round(current.priceCents / Math.max(1, current.termMonths));

  return (
    <div className="card space-y-4">
      <div>
        <h3 className="font-semibold">Resize &amp; storage</h3>
        <p className="mt-1 max-w-xl text-sm text-slate-400">
          Game server tiers are fixed, all-in bundles — CPU, RAM, disk, slots and price move
          together as a set, so they can&apos;t be resized piecemeal the way a VPS plan can.
        </p>
      </div>

      <div className="rounded-xl border border-white/10 bg-white/[0.03] p-4">
        <div className="flex flex-wrap items-center justify-between gap-2">
          <p className="text-sm font-medium text-slate-200">{current.name}</p>
          <span className="rounded-full border border-brand-500/30 bg-brand-500/10 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-brand-300">
            current tier
          </span>
        </div>
        <dl className="mt-3 grid grid-cols-2 gap-x-4 gap-y-1.5 text-xs text-slate-400 sm:grid-cols-4">
          <div>
            <dt className="text-slate-500">CPU</dt>
            <dd className="text-slate-200">{current.cpuCores} vCPU</dd>
          </div>
          <div>
            <dt className="text-slate-500">RAM</dt>
            <dd className="text-slate-200">{(current.ramMB / 1024).toFixed(current.ramMB % 1024 ? 1 : 0)} GB</dd>
          </div>
          <div>
            <dt className="text-slate-500">Disk</dt>
            <dd className="text-slate-200">
              {effectiveDiskGB} GB
              {extraDiskGB > 0 && <span className="text-slate-500"> ({current.diskGB} + {extraDiskGB})</span>}
            </dd>
          </div>
          {current.slots != null && (
            <div>
              <dt className="text-slate-500">Slots</dt>
              <dd className="text-slate-200">{current.slots}</dd>
            </div>
          )}
        </dl>
        <p className="mt-2 text-xs text-slate-500">{fmtMoney(monthly)}/mo</p>
      </div>

      {otherTiers.length > 0 && (
        <div>
          <p className="section-label mb-2">Other tiers in this game family</p>
          <div className="space-y-2">
            {otherTiers.map((t) => {
              const tMonthly = Math.round(t.priceCents / Math.max(1, t.termMonths));
              const bigger = t.ramMB > current.ramMB || t.diskGB > current.diskGB;
              return (
                <div
                  key={t.id}
                  className="flex flex-wrap items-center justify-between gap-2 rounded-lg border border-white/[0.06] bg-navy-950/40 px-3 py-2 text-xs"
                >
                  <div className="flex flex-wrap items-center gap-x-3 gap-y-1 text-slate-300">
                    <span className="font-medium text-slate-200">{t.name}</span>
                    <span className="text-slate-500">
                      {t.cpuCores} vCPU · {(t.ramMB / 1024).toFixed(t.ramMB % 1024 ? 1 : 0)} GB · {t.diskGB} GB
                      {t.slots != null ? ` · ${t.slots} slots` : ""}
                    </span>
                  </div>
                  <span className={bigger ? "font-semibold text-emerald-300" : "font-semibold text-slate-300"}>
                    {fmtMoney(tMonthly)}/mo
                  </span>
                </div>
              );
            })}
          </div>
        </div>
      )}

      <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] px-4 py-3 text-xs text-slate-400">
        Want a bigger (or smaller) tier, or more disk on {hostname}? Our team moves you across
        manually, keeping your world/data intact —{" "}
        <a
          href={supportHref}
          className="text-brand-300 underline decoration-brand-500/40 underline-offset-2 hover:text-brand-200"
        >
          contact support
        </a>
        .
      </div>
    </div>
  );
}

/**
 * Shared per-server DEDICATED IP purchase core — the money path for adding a
 * dedicated public IPv4 to a server that does NOT already have one.
 *
 * Mirrors lib/disk-expand.ts (which itself mirrors lib/resize.ts) line-for-line
 * in shape: a pure `*Quote` function re-validated by `apply*`, used by both the
 * wallet flow (lib/actions-dedicated-ip.ts) and the Stripe confirm route so a
 * paid checkout can apply the purchase immediately. Plain server module (NOT
 * "use server").
 *
 * ─── WHY THIS CANNOT DOUBLE-CHARGE ──────────────────────────────────────────
 * Identical argument to lib/disk-expand.ts: one quote function, one wallet debit
 * inside the same transaction that creates the job, and the card path credits
 * only the card remainder before debiting the full proration on confirm.
 *
 * ─── ROLLBACK SAFETY (real infra, real money) ───────────────────────────────
 * The actual IP claim + OVH Virtual MAC creation + Proxmox network reconfig all
 * happen in the WORKER (`ASSIGN_DEDICATED_IP`, worker/index.ts), never here —
 * exactly like DISK_EXPAND never touches Proxmox synchronously inside the
 * action. That keeps "charge" and "allocate" as two separate steps that can
 * each fail independently without corrupting the other:
 *   - If nothing is charged, no job is ever created (both happen in one
 *     `$transaction`), so nothing is ever allocated.
 *   - If the job's `allocateDedicatedIp` call can't claim a pool IP (or OVH
 *     errors), it throws BEFORE touching the DB (see lib/dedicated-ip.ts's own
 *     rollback-on-failure) and the job fails/retries; a terminal failure is
 *     refunded by `reconcileFailedJob` in worker/index.ts, mirroring RESIZE.
 */
import { db } from "./db";
import { debitWallet, InsufficientBalanceError } from "./wallet";
import { invoiceCreateData } from "./invoices";
import { remainingMonths } from "./proration";
import { extraDiskProrateCents } from "./extra-disk";
import { dedicatedIpMonthlyCents, freeCount } from "./dedicated-ip";

export class DedicatedIpPurchaseError extends Error {}

function loadServer(serverId: string) {
  return db.server.findUnique({ where: { id: serverId }, include: { dedicatedIp: true } });
}

type QuotedServer = NonNullable<Awaited<ReturnType<typeof loadServer>>>;

export type DedicatedIpQuote = {
  server: QuotedServer;
  monthlyCents: number;
  /** One-off charge for the remainder of the CURRENT paid term. */
  prorateCents: number;
};

/**
 * Validate a dedicated-IP purchase and compute the prorated charge over the
 * ACTUAL remaining duration — identical maths to `diskExpandQuote` (a flat
 * monthly add-on × every remaining month; null expiresAt on free/admin servers
 * => 0). Throws DedicatedIpPurchaseError with a user-facing message on any
 * guard failure. Does NOT check ownership — callers must do that.
 */
export async function dedicatedIpPurchaseQuote(serverId: string): Promise<DedicatedIpQuote> {
  const server = await loadServer(serverId);
  if (!server) throw new DedicatedIpPurchaseError("Not found");
  if (server.dedicatedIp) {
    throw new DedicatedIpPurchaseError("This server already has a dedicated IP.");
  }
  if (!["RUNNING", "STOPPED"].includes(server.status)) {
    throw new DedicatedIpPurchaseError("Server is busy — wait for the current operation to finish.");
  }
  if (!server.vmid) throw new DedicatedIpPurchaseError("This server hasn't finished provisioning yet.");

  // A DB-level check only — the authoritative claim happens atomically in the
  // worker (allocateDedicatedIp). This just avoids charging a customer for a
  // pool we already know is empty.
  const available = await freeCount();
  if (available <= 0) {
    throw new DedicatedIpPurchaseError(
      "No dedicated IPs are available in the pool right now — please contact support and we'll get one allocated.",
    );
  }

  const monthlyCents = await dedicatedIpMonthlyCents();
  let prorateCents = 0;
  if (!server.isFree && server.expiresAt) {
    // Reuses the generic "flat monthly amount × remaining months" prorate
    // formula lib/extra-disk.ts already owns for the disk add-on — it is not
    // disk-specific despite the name (`Math.max(0, Math.round(monthly * months))`),
    // and this is exactly the shape of a flat monthly surcharge like the
    // dedicated-IP price, so it is reused rather than redefined a third time.
    prorateCents = extraDiskProrateCents(monthlyCents, remainingMonths(server.expiresAt, Date.now()));
  }
  return { server, monthlyCents, prorateCents };
}

/**
 * Apply the purchase: (optionally) debit the wallet for the prorated charge,
 * record the wallet transaction + PAID invoice, and queue the
 * ASSIGN_DEDICATED_IP job the worker performs against Proxmox/OVH. Re-validates
 * every guard so it is safe to call from the unauthenticated confirm route.
 * Throws DedicatedIpPurchaseError on any guard failure.
 *
 * `chargeCents` overrides the recomputed proration — the paid path passes the
 * exact amount the customer paid into their wallet at checkout so the debit
 * here nets to zero against that credit (mirrors lib/disk-expand.ts).
 */
export async function applyDedicatedIpPurchase(opts: {
  serverId: string;
  actorUserId: string;
  chargeCents?: number;
}): Promise<void> {
  const quote = await dedicatedIpPurchaseQuote(opts.serverId);
  const { server, monthlyCents } = quote;
  const prorateCents = opts.chargeCents ?? quote.prorateCents;

  const pending = await db.job.count({
    where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } },
  });
  if (pending > 0) throw new DedicatedIpPurchaseError("Another operation is already in progress on this server.");

  try {
    await db.$transaction(async (tx) => {
      if (prorateCents > 0) {
        await debitWallet(tx, server.userId, prorateCents);
        await tx.walletTransaction.create({
          data: {
            userId: server.userId,
            amountCents: -prorateCents,
            description: `Dedicated IP add-on (prorated) — ${server.hostname}`,
          },
        });
        await tx.invoice.create({
          data: invoiceCreateData({
            userId: server.userId,
            description: `Dedicated IP add-on (prorated) — ${server.hostname}`,
            status: "PAID",
            lineItems: [
              {
                description:
                  `Dedicated IP — prorated for remaining term (${server.hostname}). ` +
                  `Renews at $${(monthlyCents / 100).toFixed(2)}/mo.`,
                qty: 1,
                unitCents: prorateCents,
                amountCents: prorateCents,
              },
            ],
          }),
        });
      }
      // Record the amount charged AND the monthly rate on the job so the worker
      // can deliver it, and so a terminal failure can be REVERSED (refund the
      // charge, release any IP it managed to claim) — money is committed here,
      // before the job runs.
      await tx.job.create({
        data: {
          type: "ASSIGN_DEDICATED_IP",
          serverId: server.id,
          payload: { prorateCents, monthlyCents } as any,
        },
      });
      await tx.auditLog.create({
        data: {
          userId: opts.actorUserId,
          action: "server.dedicated_ip_purchase",
          detail: `${server.id} prorate=${prorateCents} monthly=${monthlyCents}`,
        },
      });
    });
  } catch (e) {
    if (e instanceof InsufficientBalanceError) {
      throw new DedicatedIpPurchaseError("Insufficient balance — top up your wallet first.");
    }
    throw e;
  }
}

"use server";

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser, assertNotImpersonating } from "./auth";
import { InsufficientBalanceError } from "./wallet";
import { dedicatedIpPurchaseQuote, applyDedicatedIpPurchase, DedicatedIpPurchaseError } from "./dedicated-ip-purchase";
import { createDedicatedIpCheckout, type EmbeddedCheckout } from "./stripe";
import { walletSplit } from "./wallet-split";
import { emailVerificationError } from "./email-verification";

/**
 * Post-deploy "Add dedicated IP": give an ALREADY-provisioned server (VPS or
 * game) its own dedicated public IPv4, for a server that doesn't already have
 * one. Money path is a carbon copy of lib/actions-disk.ts expandServerDisk:
 *   quote -> walletSplit -> (card remainder ? Stripe checkout : apply now).
 * The wallet is only ever debited by applyDedicatedIpPurchase, and only after
 * the card portion has cleared, so displayed === charged and nothing is
 * charged twice. The actual IP claim + network reconfiguration happens
 * asynchronously in the worker (ASSIGN_DEDICATED_IP) — see
 * lib/dedicated-ip-purchase.ts's header for why that split is deliberate.
 */
async function ownedServer(serverId: string) {
  const user = await requireUser();
  const server = await db.server.findUnique({ where: { id: serverId }, include: { dedicatedIp: true } });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, server };
}

export async function purchaseDedicatedIp(
  serverId: string,
  useWallet: boolean = true,
): Promise<{ error?: string; checkout?: EmbeddedCheckout }> {
  // Spend path: block wallet debits while an admin is impersonating — same
  // guard as every other money movement on a server (resizeServer,
  // expandServerDisk).
  await assertNotImpersonating();
  const { user, server } = await ownedServer(serverId);
  // Purchase gate: this is an irreversible real-infra charge. See
  // lib/email-verification.ts.
  const unverified = await emailVerificationError(user);
  if (unverified) return { error: unverified };

  if (server.dedicatedIp) return { error: "This server already has a dedicated IP." };

  // Reject while another job is in flight, and only from a steady run state.
  // (applyDedicatedIpPurchase re-checks both; this returns the friendlier
  // message first.)
  if (!["RUNNING", "STOPPED"].includes(server.status)) {
    return { error: "Server must be running or stopped to add a dedicated IP." };
  }
  const pending = await db.job.count({ where: { serverId, status: { in: ["QUEUED", "RUNNING"] } } });
  if (pending > 0) return { error: "Another operation is already in progress on this server." };

  let quote;
  try {
    quote = await dedicatedIpPurchaseQuote(serverId);
  } catch (e) {
    if (e instanceof DedicatedIpPurchaseError) return { error: e.message };
    throw e;
  }
  const { prorateCents } = quote;

  // Wallet-aware split — identical logic to the resize/disk-expand flows.
  // AddDedicatedIp computes the same split (lib/wallet-split.ts) so
  // displayed === charged.
  const { cardCents } = walletSplit({
    dueCents: prorateCents,
    balanceCents: user.balanceCents,
    useWallet,
  });

  if (cardCents > 0) {
    const checkout = await createDedicatedIpCheckout(user, cardCents, {
      serverId,
      hostname: server.hostname,
      prorateCents,
    });
    if (!checkout) {
      return {
        error: `A dedicated IP costs $${(prorateCents / 100).toFixed(2)} for the rest of your term, and card payments aren't set up — top up your wallet first.`,
      };
    }
    return { checkout };
  }

  try {
    await applyDedicatedIpPurchase({ serverId, actorUserId: user.id });
  } catch (e) {
    if (e instanceof DedicatedIpPurchaseError) return { error: e.message };
    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
    throw e;
  }
  revalidatePath(`/dashboard/servers/${serverId}`);
  return {};
}

