/**
 * ASSIGN_DEDICATED_IP — deliver a dedicated public IPv4 to an ALREADY-
 * provisioned server (VPS or game) that just paid for one
 * (lib/dedicated-ip-purchase.ts applyDedicatedIpPurchase). Payment already
 * happened at enqueue time; this handler is responsible only for claiming the
 * IP and reconfiguring the VM's network.
 *
 * Reuses the EXACT same allocate + reconfigure sequence `suspend(job, true)`
 * (UNSUSPEND) already runs to re-give a server its dedicated IP after it comes
 * back — see that function's `wantDedicated` branch above. Nothing here
 * invents new Proxmox/iptables behavior:
 *   1. `allocateDedicatedIp` claims a FREE pool IP + creates the OVH Virtual
 *      MAC (idempotent — a retry after a partial failure returns the same
 *      already-ASSIGNED IP rather than claiming a second one).
 *   2. The VM's `net0`/`ipconfig0` are pointed at it.
 *   3. `Server.ipAddress`/`sshPort` are updated (`sshPort: null` — dedicated
 *      servers own every port directly, and NULL is how a NAT slot is
 *      released back to the pool; `syncPortForwards`'s query already excludes
 *      any server with `sshPort: null`, so the old NAT/SSH forward rules are
 *      torn down on the very next sync below).
 *   4. `wantsDedicatedIp` is persisted so a LATER suspend/unsuspend cycle
 *      re-allocates this server a dedicated IP instead of silently dropping
 *      it back to NAT — `suspend(job, true)`'s game branch reads exactly this
 *      flag with no other fallback.
 *
 * A power cycle is required for the new net0/ipconfig0 to take effect (cloud-
 * init only re-applies network config at boot), so a running VM is stopped and
 * started, mirroring `resize()`'s own CPU/RAM power-cycle above. Listed in
 * VM_STATE_FAILURE_JOBS (like RESIZE) since a failure here can leave the VM
 * mid-power-cycle; `reconcileFailedDedicatedIp` below refunds the charge and
 * releases any IP this run managed to claim.
 */
async function assignDedicatedIp(job: Job) {
  const server = await loadServer(job);
  if (server.dedicatedIp) {
    // Already has one — a previous attempt at this same job must have
    // completed the DB/network side before failing on a later step (or this is
    // a harmless re-run). Nothing left to deliver.
    return;
  }

  if (SANDBOX) {
    // Sandbox: synthesize a dedicated IP without any OVH/Proxmox call, but
    // still create the real DedicatedIp row (unlike provision()'s SANDBOX
    // path) — this is a customer-facing PAID purchase, and `server.dedicatedIp`
    // must actually reflect it so the dashboard, billing and a later
    // suspend/unsuspend cycle all see a real dedicated IP.
    const address = sandboxIp(server.vmid ?? 0);
    await db.$transaction([
      db.dedicatedIp.create({
        data: { address, ovhBlock: `${address}/32`, status: "ASSIGNED", serverId: server.id, purpose: "CUSTOMER" },
      }),
      db.server.update({
        where: { id: server.id },
        data: { ipAddress: address, sshPort: null, wantsDedicatedIp: true },
      }),
    ]);
    await notify(server.userId, `Dedicated IP added to ${server.hostname} (sandbox)`,
      `Your server now connects on ${address} (no real network was touched).`,
      `/dashboard/servers/${server.id}`);
    return;
  }

  if (!server.vmid) throw new Error("assign dedicated ip: server has no VM yet");
  const d = await allocateDedicatedIp(server.id, server.vmid);
  if (!d) throw new Error("assign dedicated ip: no free IP available in the pool (or OVH not configured)");

  const { conn } = await nodeFor(server);
  const wasRunning = server.status === "RUNNING";
  await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
    net0: `virtio=${d.virtualMac},bridge=vmbr0`,
    ipconfig0: `ip=${d.address}/32,gw=${d.gateway}`,
  });
  await db.server.update({
    where: { id: server.id },
    data: { ipAddress: d.address, sshPort: null, wantsDedicatedIp: true },
  });
  if (wasRunning) {
    try {
      const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/shutdown`, { timeout: 60 });
      await conn.waitForTask(stopUpid, 120_000);
    } catch {
      const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/stop`, {});
      await conn.waitForTask(stopUpid);
    }
    const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
    await conn.waitForTask(startUpid);
  }
  // The server no longer holds a NAT SSH port (sshPort is now null) — reconcile
  // the shared DNAT chain so its old port-forward/SSH rules are removed.
  await syncPortForwardsBestEffort(`assign dedicated ip ${server.hostname}`);
  // A Minecraft subdomain's SRV record points at the old ip:port — resync now
  // that the address changed, exactly like addPortForward/deletePortForward do.
  if (server.subdomain) await db.job.create({ data: { type: "SYNC_GAME_DNS", serverId: server.id } });
  await notify(server.userId, `Dedicated IP added to ${server.hostname}`,
    `Your server now connects on ${d.address}.`,
    `/dashboard/servers/${server.id}`);
}

