"use client";

import { useState, useTransition } from "react";
import { purchaseDedicatedIp } from "@/lib/actions-dedicated-ip";
import { StripeCheckoutModal } from "@/components/customer/StripeCheckoutModal";
import { fmtMoney } from "@/components/ui/primitives";
import { walletSplit, STRIPE_MIN_CENTS } from "@/lib/wallet-split";
import { remainingMonths } from "@/lib/proration";
import { extraDiskProrateCents } from "@/lib/extra-disk";

/**
 * Post-deploy "Add dedicated IP" — give this server its own public IPv4
 * instead of sitting behind shared NAT. Only rendered when the server doesn't
 * already have one (`!dedicated`).
 *
 * Money maths mirrors AddStorage.tsx exactly: a flat monthly surcharge ×
 * remaining term (lib/extra-disk.ts extraDiskProrateCents, reused here — it is
 * a generic "flat monthly amount" prorate, not disk-specific), then
 * lib/wallet-split.ts for the wallet/card split. What is shown here is what
 * gets charged; the server recomputes it authoritatively before taking a cent.
 */
export function AddDedicatedIp({
  serverId,
  hostname,
  monthlyCents,
  expiresAt,
  isFree,
  walletBalanceCents,
  disabled,
}: {
  serverId: string;
  hostname: string;
  /** Current admin-configured dedicated-IP monthly price. */
  monthlyCents: number;
  /** ISO string of the current term end, or null (free/admin servers). */
  expiresAt: string | null;
  isFree: boolean;
  walletBalanceCents: number;
  disabled?: boolean;
}) {
  const [error, setError] = useState<string | null>(null);
  const [checkout, setCheckout] = useState<{ clientSecret: string; publishableKey: string } | null>(null);
  const [pending, start] = useTransition();
  const [useWallet, setUseWallet] = useState(walletBalanceCents > 0);

  const prorate =
    isFree || !expiresAt
      ? 0
      : extraDiskProrateCents(monthlyCents, remainingMonths(new Date(expiresAt), Date.now()));

  const split = walletSplit({ dueCents: prorate, balanceCents: walletBalanceCents, useWallet });
  const { walletApplied, cardCents } = split;

  return (
    <div className="card">
      <div className="mb-1 flex flex-wrap items-center justify-between gap-2">
        <h2 className="font-semibold">Add dedicated IP</h2>
        <span className="text-xs text-slate-400">{fmtMoney(monthlyCents)}/mo</span>
      </div>
      <p className="mb-4 text-sm text-slate-400">
        Give this server its own public IPv4 — every port is reachable directly, with no NAT port
        forwarding needed.
      </p>

      {error && (
        <div className="mb-4 rounded-xl border border-red-500/30 bg-red-500/10 px-4 py-3 text-sm text-red-400">
          {error}
        </div>
      )}

      <div className="space-y-3 rounded-xl border border-white/[0.06] bg-white/[0.02] px-4 py-3">
        {prorate > 0 && walletBalanceCents > 0 && (
          <label className="flex items-center justify-between gap-3 text-xs text-slate-300">
            <span className="flex items-center gap-2">
              <input type="checkbox" checked={useWallet} onChange={(e) => setUseWallet(e.target.checked)} />
              Apply my balance ({fmtMoney(walletBalanceCents)})
            </span>
            <span className="text-slate-500">{useWallet ? "applied" : "off"}</span>
          </label>
        )}
        <div className="flex flex-wrap items-center justify-between gap-3">
          <p className="text-xs text-slate-400">
            Adds <span className="font-semibold">{fmtMoney(monthlyCents)}/mo</span> to every renewal.
            {prorate > 0 ? (
              <>
                {" "}
                Due now: <span className="font-semibold">{fmtMoney(prorate)}</span> for the rest of your
                term
                {walletApplied > 0 && (
                  <>
                    {" "}
                    — <span className="font-semibold text-emerald-300">{fmtMoney(walletApplied)}</span> from
                    your wallet
                  </>
                )}
                {cardCents > 0 ? (
                  <> and <span className="font-semibold">{fmtMoney(cardCents)}</span> by secure card checkout</>
                ) : (
                  <> (nothing due on card)</>
                )}
                .
                {split.clampedForStripeMin && (
                  <>
                    {" "}
                    Card payments have a {fmtMoney(STRIPE_MIN_CENTS)} minimum, so {fmtMoney(cardCents)} goes
                    on the card.
                  </>
                )}
                {split.belowStripeMin &&
                  (walletBalanceCents >= prorate ? (
                    <>
                      {" "}
                      That&apos;s under the {fmtMoney(STRIPE_MIN_CENTS)} card minimum, so it comes out of
                      your wallet balance.
                    </>
                  ) : (
                    <>
                      {" "}
                      That&apos;s under the {fmtMoney(STRIPE_MIN_CENTS)} card minimum, so it can only come
                      from your wallet — top up to at least {fmtMoney(prorate)} first.
                    </>
                  ))}
              </>
            ) : (
              <> Nothing due now.</>
            )}{" "}
            A short reboot applies the new network config.
          </p>
          <button
            className="btn-primary shrink-0"
            disabled={pending || disabled}
            onClick={() => {
              if (
                !window.confirm(
                  `Add a dedicated IP to ${hostname}?\n\n` +
                    `This adds ${fmtMoney(monthlyCents)}/mo to every renewal and briefly reboots the server.` +
                    (prorate > 0 ? `\n\nDue now: ${fmtMoney(prorate)} for the rest of your term.` : ""),
                )
              )
                return;
              start(async () => {
                setError(null);
                const res = await purchaseDedicatedIp(serverId, useWallet);
                if (res?.checkout) {
                  setCheckout(res.checkout);
                  return;
                }
                if (res?.error) setError(res.error);
              });
            }}
          >
            {pending
              ? "Adding…"
              : cardCents > 0
                ? `Continue to payment — ${fmtMoney(cardCents)}`
                : prorate > 0
                  ? `Add dedicated IP — ${fmtMoney(walletApplied)}`
                  : "Add dedicated IP"}
          </button>
        </div>
      </div>

      {checkout && (
        <StripeCheckoutModal
          clientSecret={checkout.clientSecret}
          publishableKey={checkout.publishableKey}
          title="Complete your dedicated IP purchase"
          onClose={() => setCheckout(null)}
        />
      )}
    </div>
  );
}

